CREATE TABLE public.anilist_catalog (
    id integer NOT NULL,
    payload jsonb NOT NULL,
    search_text text NOT NULL,
    status text,
    season_year integer,
    season text,
    format text,
    popularity integer,
    trending integer,
    mean_score integer,
    genres text[] DEFAULT '{}'::text[] NOT NULL,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    next_airing_at timestamp with time zone,
    refresh_after timestamp with time zone,
    indexed_at timestamp with time zone DEFAULT now() NOT NULL,
    is_adult boolean GENERATED ALWAYS AS (COALESCE(((payload ->> 'isAdult'::text))::boolean, false)) STORED,
    favourites integer GENERATED ALWAYS AS (((payload ->> 'favourites'::text))::integer) STORED,
    average_score integer GENERATED ALWAYS AS (((payload ->> 'averageScore'::text))::integer) STORED,
    media_updated_at bigint GENERATED ALWAYS AS (((payload ->> 'updatedAt'::text))::bigint) STORED,
    start_key integer GENERATED ALWAYS AS (
CASE
    WHEN ((payload #>> '{startDate,year}'::text[]) IS NULL) THEN NULL::integer
    ELSE (((((payload #>> '{startDate,year}'::text[]))::integer * 10000) + (COALESCE(((payload #>> '{startDate,month}'::text[]))::integer, 0) * 100)) + COALESCE(((payload #>> '{startDate,day}'::text[]))::integer, 0))
END) STORED
);


